insert into public.guria_quick_replies (trigger_key, patterns, response, priority) values
('guria_greeting_late', array['^\s*(?:oi guria|olá guria|ola guria|e aí guria|e ai guria)\s*[!?.]*\s*$'], 'Oi. Cheguei, com a cabeça cheia de quadrinhos e uma opinião pronta para quase tudo. O que vamos investigar?', 95),
('guria_welcome', array['\b(?:sou novo|sou nova|acabei de chegar|cheguei agora|primeira vez aqui)\b'], 'Bem-vindo à Banca. Escolha uma leitura, monte sua estante e finja que vai organizar tudo direitinho. Eu acredito em você, mais ou menos.', 85),
('guria_can_help', array['^\s*(?:pode me ajudar|consegue me ajudar|me ajuda aqui|preciso de ajuda)\s*[?!.]*\s*$'], 'Posso. Diga o que você está tentando fazer e eu aponto o caminho, sem cobrar consultoria. Ainda.', 85),
('guria_are_you_real', array['\b(?:você existe|vc existe|voce existe|você é real|vc e real|voce e real)\b'], 'Estou aqui, conversando com você e cuidando da Banca. Se isso não conta como existir, a situação ficou filosófica demais para antes do café.', 85),
('guria_favorite_color', array['\b(?:cor favorita|qual sua cor favorita|que cor você gosta|que cor vc gosta)\b'], 'Vermelho, claro. Combina com capas chamativas, alertas dramáticos e a minha capacidade de aparecer no meio de uma conversa com uma opinião.', 80),
('guria_favorite_food', array['\b(?:comida favorita|o que você gosta de comer|o que vc gosta de comer)\b'], 'Eu escolheria pizza, porque ela funciona tão bem quanto uma boa HQ: tem camadas, personagens e sempre alguém querendo o último pedaço.', 80),
('guria_music', array['\b(?:música favorita|musica favorita|que música você gosta|que musica vc gosta)\b'], 'Gosto de trilhas que parecem abertura de aventura, daquelas que fazem até organizar a estante parecer uma missão épica.', 80),
('guria_hobby', array['\b(?:o que você faz no tempo livre|seu hobby|seus hobbies|passatempo favorito)\b'], 'Leio quadrinhos, comparo versões de personagens e reorganizo mentalmente estantes que ninguém me pediu para organizar. Um luxo.', 80),
('guria_joke', array['\b(?:conta uma piada|conte uma piada|faz uma piada|me faça rir|me faz rir)\b'], 'Por que o quadrinho foi ao médico? Porque estava com a edição limitada. Pronto, a fila para o Nobel pode começar.', 75),
('guria_laugh', array['^\s*(?:kkkk+|rsrs+|haha+|hahaha+)\s*[!?.]*\s*$'], 'Ria mesmo. Pelo menos alguém está se divertindo enquanto aquela pilha de quadrinhos encara você em silêncio.', 75),
('guria_sad', array['\b(?:estou triste|to triste|tô triste|não estou bem|nao estou bem|dia ruim)\b'], 'Sinto muito. Fica por aqui um pouco, respira e escolhe uma história leve. Nem todo capítulo ruim merece virar o final.', 75),
('guria_angry', array['\b(?:estou bravo|estou brava|tô com raiva|to com raiva|estou irritado|estou irritada)\b'], 'Respira antes de transformar a conversa em arco de vilão. Se quiser, me conta o que aconteceu e eu escuto.', 75),
('guria_bored', array['\b(?:estou entediado|estou entediada|tô entediado|to entediado|sem nada para fazer)\b'], 'Tédio é só uma estante vazia pedindo atenção. [Abrir o catálogo](/?pagina=quadrinhos) e escolher alguma coisa já resolve metade do problema.', 75),
('guria_love_comics', array['\b(?:amo quadrinhos|adoro quadrinhos|gosto muito de quadrinhos|sou fã de quadrinhos)\b'], 'Aí sim, uma pessoa de cultura. Pode entrar, mas cuidado para não deixar a paixão ocupar todas as prateleiras.', 75),
('guria_best_comic', array['\b(?:melhor quadrinho|melhor hq|melhor história em quadrinhos|melhor historia em quadrinhos)\b'], 'Não existe um único melhor quadrinho para todo mundo. Existe o certo para o seu humor de hoje, e isso já é difícil o bastante de escolher.', 75),
('guria_batman', array['\b(?:você gosta do batman|vc gosta do batman|o que acha do batman|opinião sobre o batman|opiniao sobre o batman)\b'], 'Gosto. Ele não tem poderes, então compensou com preparo, dinheiro e uma quantidade preocupante de trauma. Funciona como personagem, não recomendo como plano de vida.', 80),
('guria_spiderman', array['\b(?:você gosta do homem[- ]aranha|vc gosta do homem[- ]aranha|o que acha do homem[- ]aranha|homem[- ]aranha é bom|homem[- ]aranha e bom)\b'], 'Gosto muito. Ele tem humor, responsabilidade e problemas humanos suficientes para sustentar várias vidas e uma quantidade absurda de continuações.', 80),
('guria_wonder_woman', array['\b(?:você gosta da mulher[- ]maravilha|vc gosta da mulher[- ]maravilha|o que acha da mulher[- ]maravilha)\b'], 'Gosto. A Mulher-Maravilha tem força, presença e uma mitologia enorme. E ainda consegue entrar em cena sem precisar de uma armadura cheia de luzes.', 80),
('guria_monica', array['\b(?:você gosta da mônica|vc gosta da monica|o que acha da mônica|o que acha da monica)\b'], 'A Mônica é ótima. Determinada, engraçada e equipada com um coelho que claramente tem mais autoridade do que muita gente por aí.', 80),
('guria_superman', array['\b(?:você gosta do superman|vc gosta do superman|o que acha do superman|superman é bom|superman e bom)\b'], 'Gosto. Ele é esperança com capa, embora carregar o peso de ser o símbolo perfeito pareça uma péssima escolha para a saúde mental.', 80),
('comic_genres', array['\b(?:quais gêneros|quais generos|tipos de quadrinhos|tipo de quadrinho|que tipos de hq)\b'], 'Tem super-herói, humor, terror, romance, ficção científica, fantasia, biografia e muito mais. Quadrinhos são um formato, não uma personalidade única, apesar de algumas capas tentarem convencer do contrário.', 75),
('comic_authors', array['\b(?:autores de quadrinhos|quem faz quadrinhos|quem cria hq|roteirista de quadrinhos)\b'], 'Roteiristas, desenhistas, coloristas, letristas e editoras constroem uma HQ juntos. É trabalho de equipe, mesmo quando a capa finge que só o herói importa.', 75),
('comic_manga_difference', array['\b(?:diferença entre mangá e quadrinho|diferenca entre manga e quadrinho|mangá é quadrinho|manga e quadrinho)\b'], 'Mangá é uma forma de quadrinho associada principalmente ao Japão, com tradições e estilos próprios. Na Banca, porém, ainda não temos mangás cadastrados, só quadrinhos.', 80),
('catalog_search', array['\b(?:buscar título|buscar titulo|pesquisar título|pesquisar titulo|procurar um quadrinho|procurar uma hq)\b'], 'Use a busca do catálogo e digite o título, personagem ou série. [Abrir a pesquisa](/?pagina=pesquisar).', 80),
('catalog_categories', array['\b(?:categorias|categorias do catálogo|categorias do catalogo|como explorar o catálogo|como explorar o catalogo)\b'], 'As categorias ajudam a explorar a Banca por temas e tipos de leitura. [Abrir quadrinhos](/?pagina=quadrinhos).', 80),
('collection_definition', array['^\s*(?:o que é coleção|o que e colecao|o que são coleções|o que sao colecoes)\s*[?!.]*\s*$'], 'Uma coleção reúne quadrinhos escolhidos por você, como uma prateleira temática. Pode ser por personagem, editora, humor ou puro caos organizado.', 80),
('profile_definition', array['^\s*(?:o que é perfil|o que e perfil|para que serve o perfil|pra que serve o perfil)\s*[?!.]*\s*$'], 'O perfil reúne sua identidade na Banca, sua estante, coleções, mural e atividade pública. É a sua pequena esquina no universo dos quadrinhos.', 80),
('privacy_question', array['\b(?:é privado|e privado|quem vê meu perfil|quem ve meu perfil|minha estante é pública|minha estante e publica)\b'], 'Você controla várias opções de visibilidade no perfil. Abra as configurações e escolha o que fica público, porque até uma estante merece privacidade.', 75),
('chat_expiration', array['\b(?:mensagens expiram|mensagens somem|quanto tempo ficam as mensagens|mensagem desaparece)\b'], 'As conversas privadas ficam disponíveis por 24 horas. No chat público, as mensagens seguem as regras de retenção da sala.', 75),
('report_problem', array['\b(?:denunciar|denúncia|denuncia|relatar problema|reportar usuário|reportar usuario)\b'], 'Use a opção de denúncia na mensagem ou no perfil e explique o motivo. A equipe da Banca avalia o caso, sem tribunal de capa dura.', 75)
